// What the setup tabs say and the commands they copy or run.

import type { ProxyAddress, ProxySetupTab, ProxyStatus } from '../types'

export const MAGIC_HOST = 'claude.proxy'

export const SETUP_TABS: { tab: ProxySetupTab; label: string; hotkey: string }[] = [
  { tab: 'browser', label: 'Browser', hotkey: '1' },
  { tab: 'ios', label: 'iOS', hotkey: '2' },
  { tab: 'android', label: 'Android', hotkey: '3' },
  { tab: 'cli', label: 'macOS / CLI', hotkey: '4' },
]

export type Browser = { name: string; app: string; slug: string }

/** Chromium browsers that honour --proxy-server and the SPKI allow-list. */
export const BROWSER_CANDIDATES: Browser[] = [
  { name: 'Google Chrome', app: 'Google Chrome.app', slug: 'chrome' },
  { name: 'Chrome Canary', app: 'Google Chrome Canary.app', slug: 'chrome-canary' },
  { name: 'Chromium', app: 'Chromium.app', slug: 'chromium' },
  { name: 'Microsoft Edge', app: 'Microsoft Edge.app', slug: 'edge' },
  { name: 'Brave', app: 'Brave Browser.app', slug: 'brave' },
]

export type SetupFacts = {
  status: ProxyStatus
  dataDir: string
  listen: 'local' | 'lan'
}

function proxyAddress(status: ProxyStatus): string {
  return `127.0.0.1:${status.port}`
}

/** The address a phone on the same network enters as its proxy server. */
export function phoneAddress(facts: SetupFacts): ProxyAddress | null {
  return facts.status.lan.find(entry => entry.isPrimary) ?? null
}

/** One client of a tab and exactly what goes into its proxy settings. */
export type ProxyTarget = {
  client: string
  /** What to enter as the server; null when this Mac has no address for it. */
  host: string | null
  port: number
  /** Where it goes, or what sets it. */
  how: string
  /** Reached over the network: needs Proxy reachable from = lan. */
  isRemote: boolean
}

export function proxyTargets(facts: SetupFacts, tab: ProxySetupTab): ProxyTarget[] {
  const port = facts.status.port
  const phone = phoneAddress(facts)?.address ?? null
  switch (tab) {
    case 'browser':
      return [{ client: 'Separate browser', host: '127.0.0.1', port, how: 'set by the Open button', isRemote: false }]
    case 'ios':
      return [
        { client: 'iOS Simulator', host: '127.0.0.1', port, how: 'macOS system proxy ("system proxy on")', isRemote: false },
        { client: 'iPhone / iPad', host: phone, port, how: 'Wi-Fi → (i) → Configure Proxy → Manual', isRemote: true },
      ]
    case 'android':
      return [
        { client: 'Android emulator', host: '10.0.2.2', port, how: 'set by "Android → proxy"', isRemote: false },
        { client: 'Android on USB', host: '127.0.0.1', port, how: 'set by "Android → proxy" (adb reverse)', isRemote: false },
        { client: 'Android on Wi-Fi', host: phone, port, how: 'Wi-Fi → Modify → Proxy: Manual', isRemote: true },
      ]
    default:
      return [{ client: 'curl, scripts, system proxy', host: '127.0.0.1', port, how: 'HTTPS_PROXY / -x / networksetup', isRemote: false }]
  }
}

/** What the phone steps say before step 1 when the phone cannot reach the proxy yet. */
function phonePreface(facts: SetupFacts): string {
  const phone = phoneAddress(facts)
  if (!phone) {
    return facts.status.lan.length === 0 && facts.status.phase !== 'running'
      ? 'Start the proxy to find the address the phone should use.\n\n'
      : 'This Mac has no address a phone could reach: connect it to Wi-Fi or Ethernet, on the same network as the phone.\n\n'
  }
  return facts.listen === 'lan'
    ? ''
    : 'First turn on **Listen on LAN** (the button above): the proxy listens on this Mac only now, so the phone cannot reach it.\n\n'
}

export function browserArgs(facts: SetupFacts, browser: Browser): string[] {
  const spki = facts.status.ca?.spki ?? []
  return [
    `--user-data-dir=${facts.dataDir}/browser/${browser.slug}`,
    `--proxy-server=http://${proxyAddress(facts.status)}`,
    // Chrome skips the proxy for localhost unless told otherwise.
    '--proxy-bypass-list=<-loopback>',
    `--ignore-certificate-errors-spki-list=${spki.join(',')}`,
    '--no-first-run',
    '--no-default-browser-check',
    `http://${MAGIC_HOST}/`,
  ]
}

export function shellQuote(text: string): string {
  return /^[\w@%+=:,./-]+$/.test(text) ? text : `'${text.replace(/'/g, `'\\''`)}'`
}

export function browserCommand(facts: SetupFacts, browser: Browser, appPath: string): string {
  return ['open', '-na', appPath, '--args', ...browserArgs(facts, browser)].map(shellQuote).join(' ')
}

export function systemProxyCommands(port: number, service = 'Wi-Fi'): { on: string; off: string } {
  const s = shellQuote(service)
  return {
    on: `networksetup -setwebproxy ${s} 127.0.0.1 ${port} && networksetup -setsecurewebproxy ${s} 127.0.0.1 ${port}`,
    off: `networksetup -setwebproxystate ${s} off && networksetup -setsecurewebproxystate ${s} off`,
  }
}

export function trustCommand(caPath: string): string {
  return `security add-trusted-cert -r trustRoot -k ~/Library/Keychains/login.keychain-db ${shellQuote(caPath)}`
}

export function untrustCommand(caPath: string): string {
  return `security remove-trusted-cert ${shellQuote(caPath)}`
}

export const ANDROID_NETWORK_CONFIG = `<!-- res/xml/network_security_config.xml -->
<network-security-config>
  <debug-overrides>
    <trust-anchors>
      <certificates src="user" />
    </trust-anchors>
  </debug-overrides>
</network-security-config>

<!-- AndroidManifest.xml, on <application> -->
android:networkSecurityConfig="@xml/network_security_config"`

/** The copyable commands each tab offers, by key. */
export function setupCommands(facts: SetupFacts): Record<string, string> {
  const port = facts.status.port
  const ca = facts.status.ca?.path ?? `${facts.dataDir}/ca/ca.pem`
  const proxy = systemProxyCommands(port)
  return {
    'sys-on': proxy.on,
    'sys-off': proxy.off,
    trust: trustCommand(ca),
    untrust: untrustCommand(ca),
    'sim-ca': `xcrun simctl keychain booted add-root-cert ${shellQuote(ca)}`,
    'adb-on': `adb shell settings put global http_proxy 10.0.2.2:${port}`,
    'adb-off': 'adb shell settings put global http_proxy :0',
    'android-config': ANDROID_NETWORK_CONFIG,
    curl: `curl -x http://${proxyAddress(facts.status)} --cacert ${shellQuote(ca)} https://example.com/`,
    env: [
      `export HTTPS_PROXY=http://${proxyAddress(facts.status)} HTTP_PROXY=http://${proxyAddress(facts.status)}`,
      `export NODE_EXTRA_CA_CERTS=${shellQuote(ca)} SSL_CERT_FILE=${shellQuote(ca)} REQUESTS_CA_BUNDLE=${shellQuote(ca)}`,
    ].join('\n'),
  }
}

export function browserGuide(facts: SetupFacts, found: readonly Browser[]): string {
  const browsers = found.length > 0 ? found.map(b => b.name).join(', ') : 'none (looked for Chrome, Chromium, Edge, Brave)'
  return `### A separate browser whose traffic all goes through the proxy

The button below starts a **new instance** of a Chromium browser with a profile of its own
(\`${facts.dataDir}/browser/…\`) that:

- goes through the proxy \`${proxyAddress(facts.status)}\`, **localhost included** (\`--proxy-bypass-list=<-loopback>\`);
- trusts the proxy's certificates by the SPKI hash of their key, so **nothing goes into the keychain**;
- leaves your everyday profile alone: logins, extensions and tabs stay apart, and the profile is kept between runs.

Found: ${browsers}.

It opens on \`http://${MAGIC_HOST}/\`: if that page shows, the browser is going through the proxy.
A yellow "unsupported command-line flag" bar is expected; it is how Chrome flags the trust switch.

**Firefox** (by hand): a separate profile (\`firefox -P\`), then Settings → Network Settings → Manual proxy
configuration, \`127.0.0.1\` port \`${facts.status.port}\` for HTTP and HTTPS. In \`about:config\` set
\`network.proxy.allow_hijacking_localhost = true\`. Import the CA under Settings → Privacy & Security → Certificates →
View Certificates → Authorities → Import (\`${facts.status.ca?.path ?? 'ca.pem'}\`) and tick "Trust this CA to identify websites".`
}

export function iosGuide(facts: SetupFacts): string {
  const phone = phoneAddress(facts)
  const device = !phone
    ? phonePreface(facts)
    : `${phonePreface(facts)}The iPhone must be on the same network as this Mac's ${phone.label}.

1. **Scan the QR code above** with the Camera app (or open \`http://${phone.address}:${facts.status.port}/\` in Safari)
   → "iOS: download profile" → Allow. This page needs no proxy setting yet.
2. **Settings → Profile Downloaded → Install** (the profile is unsigned; that is expected).
3. **Settings → General → About → Certificate Trust Settings** → turn on "${caName(facts)}".
4. **Settings → Wi-Fi → (i) next to the network → Configure Proxy → Manual**:
   Server \`${phone.address}\`, Port \`${facts.status.port}\`, Authentication off.
5. Done. Rows marked **CERT** in the list mean step 3 is missing or the app pins its certificates;
   such hosts can go into the "Hosts never decrypted" option.

When you are done, set **Configure Proxy → Off** again, or the iPhone loses its network once the proxy stops.`
  return `### iOS Simulator

**Use** next to a simulator does it all: boots it, adds the proxy's root certificate
(\`xcrun simctl keychain <udid> add-root-cert\`) and turns the **macOS system proxy** on, since the
simulator has no proxy setting of its own. Every app on this Mac then goes through the proxy, Claude
Code excepted: its hosts bypass it and its own connections are tunnelled, never decrypted. The system
proxy is put back when the proxy stops, when the session ends, or if Claude Code quits.
Turn on the tracking list (**Domains**, \`d\`) to record only your app's hosts.

### iPhone / iPad

${device}`
}

export function androidGuide(facts: SetupFacts): string {
  const phone = phoneAddress(facts)
  const device = !phone
    ? phonePreface(facts)
    : `${phonePreface(facts)}The phone must be on the same network as this Mac's ${phone.label}.

1. **Scan the QR code above** with the camera (or open \`http://${phone.address}:${facts.status.port}/\` in Chrome)
   → "Android: download certificate". This page needs no proxy setting yet.
2. **Settings → Security → Encryption & credentials → Install a certificate → CA certificate** → pick the downloaded file.
3. **Settings → Wi-Fi → long-press the network → Modify → Advanced → Proxy: Manual**:
   Hostname \`${phone.address}\`, Port \`${facts.status.port}\`.
4. When you are done, set **Proxy: None** again.

A phone on USB needs none of this: "Android → proxy" reaches it through \`adb reverse\`.`
  return `### Android emulator and USB devices

1. **"Android → proxy"** points every device \`adb devices\` lists at the proxy: an emulator at
   \`10.0.2.2:${facts.status.port}\` (an emulator's name for this Mac's localhost), a USB device at
   \`127.0.0.1:${facts.status.port}\` through \`adb reverse\`. The \`local\` mode is enough for both.
   **"Revert"** sets \`:0\` again; the mod also reverts by itself when the proxy stops and when the session ends.
2. **"Open CA page"** opens \`http://${MAGIC_HOST}/\` in the device's browser. Download "Android: download certificate",
   then **Settings → Security → Encryption & credentials → Install a certificate → CA certificate**.

### Android over Wi-Fi

${device}

### Apps and user CAs

Since Android 7, apps **do not trust** certificates the user installed. Chrome does; your app will show
**CERT** rows. Give its debug build a \`network_security_config\` ("config snippet"):

\`\`\`xml
${ANDROID_NETWORK_CONFIG}
\`\`\``
}

export function cliGuide(facts: SetupFacts): string {
  const ca = facts.status.ca?.path ?? 'ca.pem'
  return `### Trusting the CA on this Mac

Needed only when traffic does not come from the separate browser, for example from Safari or through the system proxy:

\`\`\`sh
${trustCommand(ca)}
\`\`\`

To undo: \`${untrustCommand(ca)}\`.

### The macOS system proxy (Safari, the simulator, native apps)

\`\`\`sh
${systemProxyCommands(facts.status.port).on}
# turn it off:
${systemProxyCommands(facts.status.port).off}
\`\`\`

\`networksetup -listallnetworkservices\` lists the service names (\`Wi-Fi\` here). If the proxy stops while
the system proxy is on, the Mac has no network until it is turned off.

### curl and scripts

\`\`\`sh
${setupCommands(facts).curl}
${setupCommands(facts).env}
\`\`\``
}

export function caName(facts: SetupFacts): string {
  return facts.status.ca?.subject.match(/CN=([^,]+)/)?.[1] ?? 'Wirepane CA'
}

/** The oldest Node the sidecar runs on. */
export const MIN_NODE = 18

/** Where to get Node.js when this Mac has no Homebrew. */
export const NODE_DOWNLOAD = 'https://nodejs.org/en/download'

/** The major version in `node --version` output ("v22.11.0" → 22), 0 for anything else. */
export function nodeMajor(output: string): number {
  return Number(/^v(\d+)\./.exec(output.trim())?.[1] ?? 0)
}

/** A version manager's folders ("v22.11.0", …), the newest first; other names left out. */
export function newestNodeFirst(names: readonly string[]): string[] {
  const parts = (name: string) => name.slice(1).split('.').map(Number)
  return names
    .filter(name => /^v\d+\.\d+\.\d+$/.test(name))
    .sort((a, b) => {
      const [x, y] = [parts(a), parts(b)]
      return y[0]! - x[0]! || y[1]! - x[1]! || y[2]! - x[2]!
    })
}

files.types/index.d.ts:
export type ProxyFlow = {
  id: number
  ts: number
  kind: 'http' | 'ws' | 'tunnel'
  method: string
  scheme: 'http' | 'https'
  host: string
  port: number
  path: string
  status: number | null
  reqSize: number
  resSize: number
  durationMs: number | null
  contentType: string | null
  state: 'pending' | 'receiving' | 'done' | 'error'
  error: string | null
  errorCode: string | null
  client: string | null
  note?: string
  /** The ids of the rules that changed this exchange, in the order they acted. */
  rules?: string[]
  /** The client's protocol: '2' for HTTP/2, else '1.1' or '1.0'. */
  httpVersion?: string
  /** A gRPC call's status from its trailers (0 is OK), and its message. */
  grpcStatus?: number
  grpcMessage?: string
  /** A WebSocket's text and binary messages so far: client to server, server to client. */
  wsOut?: number
  wsIn?: number
  /** A text/event-stream response's events so far. */
  sseEvents?: number
  /** The request this one sent again (replay_request). */
  replayOf?: number | null
  /** Held at a rule's breakpoint, before it is sent (request) or before the client gets the answer (response). */
  held?: 'request' | 'response'
}

/** An exchange held at a breakpoint, as the proxy shows it. */
export type ProxyHeld = {
  id: number
  phase: 'request' | 'response'
  since: number
  view: { method: string; url: string; status?: number; headers: [string, string][]; body: string | null }
}

export type ProxyCa = {
  path: string
  subject: string
  fingerprint256: string
  validTo: string
  spki: string[]
}

/** One of this machine's addresses, as the sidecar ranks them for a phone. */
export type ProxyAddress = {
  address: string
  iface: string
  label: string
  kind: 'lan' | 'vpn' | 'virtual'
  isPrimary: boolean
}

export type ProxyPhase = 'stopped' | 'starting' | 'running' | 'failed'

export type ProxyStatus = {
  phase: ProxyPhase
  host: string
  port: number
  addresses: string[]
  lan: ProxyAddress[]
  runDir: string | null
  pid: number | null
  ca: ProxyCa | null
  /** The sidecar's token for its control commands (live WebSockets). */
  control?: { token: string } | null
  /** One proxy for every session on this Mac (it outlives the session that started it). */
  isShared?: boolean
  /** The running proxy's Wirepane version (another session may have started an older one). */
  proxyVersion?: string
  error: string | null
  /** No Node 18 or newer was found to run the proxy: the pane offers to install it. */
  isNodeMissing?: boolean
}

/** One rule as the rules view shows it: the file's entry, checked. */
export type ProxyRuleEntry = {
  id: string
  name: string | null
  description: string | null
  enabled: boolean
  /** What it does, in words (shared/rules.mjs describeRule). */
  summary: string
  errors: string[]
  /** It holds a script whose code is not approved yet. */
  isUntrusted: boolean
}

export type ProxyRules = {
  file: string | null
  entries: ProxyRuleEntry[]
  /** Problems of the file itself (not JSON, wrong shape). */
  fileErrors: string[]
}

/** The session's tracked domains: while on and not empty, only these are decrypted and recorded. */
export type ProxyTracking = {
  enabled: boolean
  patterns: string[]
}

export type ProxySimulator = { udid: string; name: string; runtime: string; state: string }

export type ProxyAndroidDevice = { serial: string; avd: string | null; isEmulator: boolean }

/** What the setup tabs found on this Mac, when they last looked. */
export type ProxyDevices = {
  simulators: ProxySimulator[]
  simulatorError: string | null
  avds: string[]
  android: ProxyAndroidDevice[]
  androidError: string | null
}

/** The macOS system proxy: whether it points here (scutil), on which service, and whether we set it. */
export type ProxySystemProxy = { isOn: boolean; service: string | null; isOurs: boolean }

export type ProxySetupTab = 'browser' | 'ios' | 'android' | 'cli'

export type ProxySession = { session: string; project: string; since: number }

/** What the doctor found, and the proxy process as it answered. */
export type ProxyHealth = {
  checkedAt: number | null
  findings: { level: 'ok' | 'info' | 'warn' | 'fail'; title: string; detail?: string; fix?: string; label?: string; action?: unknown }[]
  process: {
    pid: number
    version: string
    uptimeMs: number
    rss: number
    flows: number
    diskBytes: number
    sessions: ProxySession[]
    websockets: number
    pinned: number
    isShared: boolean
  } | null
}

export type ProxyView = {
  mode: 'list' | 'detail' | 'setup' | 'rules' | 'domains' | 'health' | 'held'
  selectedId: number | null
  setupTab: ProxySetupTab
  layout?: 'list' | 'tree'
  /** On the iOS and Android tabs: the simulator/emulator, or a real phone. */
  device?: 'virtual' | 'real'
  /** In the rules view: the rule whose ✕ was pressed, waiting for Remove or Keep. */
  removing?: string | null
  /** In a request's detail: the tab shown (its own default when unset), the text found in it, and which match is current. */
  detailTab?: 'request' | 'response' | 'messages' | 'events'
  detailSearch?: string
  detailMatch?: number
}

declare module 'claude-code' {
  interface PluginState {
    wirepane: {
      flows: ProxyFlow[]
      status: ProxyStatus
      view: ProxyView
      filter: string
      wanted: boolean
      nextId: number
      notice: string
      emulators: string[]
      expanded: string[]
      rules: ProxyRules
      tracking: ProxyTracking
      /** Hosts that passed through untracked, and how often, since the proxy started. */
      skipped: Record<string, number>
      devices: ProxyDevices
      systemProxy: ProxySystemProxy
      /** Simulators this session put the CA into. */
      caSimulators: string[]
      /** A long action under way (booting a simulator), shown until it ends. */
      busy: string
      /** Whether this Mac's keychain trusts the proxy CA, as last checked. */
      macTrust: 'unknown' | 'trusted' | 'untrusted'
      /** This mod's version, from its plugin.json. */
      version: string
      /** The Claude Code sessions attached to the one shared proxy, this one among them. */
      sessions: ProxySession[]
      /** Hosts passed through untouched after refusing the certificate, per client. */
      pinned: { client: string | null; host: string }[]
      /** The doctor's last findings, for the Health view. */
      health: ProxyHealth
      /** Exchanges held at a breakpoint now. */
      held: ProxyHeld[]
    }
  }
}
